'use strict';
const $=id=>document.getElementById(id);
const statuses={planned:'计划已准备',queued:'正在启动',running:'运行中',awaiting_human_review:'等待人工复核',failed:'失败',interrupted:'进程异常退出',completed:'完成',skipped:'跳过',pending:'待执行'};
let token='',samples=[],planned=null,selectedJob='',pollTimer=null,requestVersion=0,planning=false,launching=false;
function el(tag,text,cls){const node=document.createElement(tag);if(text!==undefined)node.textContent=String(text);if(cls)node.className=cls;return node;}
async function api(path,payload){if(payload!==undefined)token=(await api('/api/session')).token;const options=payload===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Review-Token':token},body:JSON.stringify(payload)};const response=await fetch(path,options);const value=await response.json();if(!response.ok)throw new Error(value.error||'请求失败');return value;}
function message(text){$('message').textContent=text;}
function invalidate(){planned=null;++requestVersion;$('start-actions').hidden=true;$('plan-view').replaceChildren(el('p','选择已变化，请重新预览计划。','empty'));$('sample-goal').textContent=samples.find(s=>s.sample_id===$('samples').value)?.goal||'';}
async function loadSamples(preferred){const data=await api('/api/samples');samples=data.samples;const chosen=preferred||$('samples').value;$('samples').replaceChildren();for(const sample of samples){const option=el('option',`${sample.sample_id} · ${sample.goal}`);option.value=sample.sample_id;$('samples').append(option);}if(!samples.length){const option=el('option','暂无样本，请先登记');option.value='';$('samples').append(option);}else if(samples.some(s=>s.sample_id===chosen))$('samples').value=chosen;$('plan').disabled=!samples.length;invalidate();await refreshMetrics();if(data.unreadable)message(`${data.unreadable} 份样本配置无法读取，请检查本机文件。`);}
function showPlan(data){const view=$('plan-view');view.replaceChildren(el('h3',data.sample_id),el('p',data.plan.goal),el('p',`本轮最多 ${data.model_stage_budget} 次模型调用，最多 ${data.max_repair_rounds} 轮返修。`));const list=el('ol',undefined,'plan-list');for(const task of data.plan.tasks){const item=el('li',`${task.name} · ${task.action==='skip'?'跳过':'执行'}`);item.append(el('small',task.reason));list.append(item);}view.append(list);const metric=data.plan.platform_data;if(metric?.status==='completed'){const source=metric.source;view.append(el('p',source.schema_version===2?`已接入截图：${source.source.title} · ${source.observed_at}`:'使用样本中登记的平台数据','data-summary'));for(const c of metric.calculations)view.append(el('p',`每百次播放${c.label}数：${c.per_100_plays??'无法计算'}`,'helper'));if(source.schema_version===2){const link=el('a','查看本轮数据原图与核对记录 ↗');link.href='/metrics?id='+encodeURIComponent(source.source.record_id);link.target='_blank';link.rel='noopener';view.append(link);for(const limitation of metric.limitations)view.append(el('p',limitation,'helper'));}}for(const reason of data.blockers)view.append(el('p',reason,'blocker'));for(const warning of data.warnings)view.append(el('p',warning,'helper'));$('start-actions').hidden=false;$('start').disabled=!data.ready||launching;}
async function refreshJobs(preferred){const data=await api('/api/jobs');const chosen=preferred||selectedJob||data.active_job||data.jobs[0]?.id||'';$('jobs').replaceChildren();for(const job of data.jobs){const option=el('option',`${job.sample_id} · ${statuses[job.status]||job.status} · ${new Date(job.created_at).toLocaleString('zh-CN')}`);option.value=job.id;$('jobs').append(option);}if(!data.jobs.length){const option=el('option','暂无记录');option.value='';$('jobs').append(option);}if(chosen){$('jobs').value=chosen;await chooseJob(chosen);}else selectedJob='';}
async function chooseJob(id){clearTimeout(pollTimer);selectedJob=id;if(!id)return;try{const data=await api('/api/jobs/detail?job='+encodeURIComponent(id));if(id!==selectedJob)return;const view=$('job-view');view.replaceChildren(el('p',`${data.sample_id} · ${statuses[data.status]||data.status}`,'job-status'),el('p',data.id,'helper'));const option=Array.from($('jobs').options).find(item=>item.value===id);if(option)option.textContent=data.sample_id+' · '+(statuses[data.status]||data.status)+' · '+new Date(data.created_at).toLocaleString('zh-CN');const live=data.workflow;view.append(el('p',`已尝试模型阶段 ${live?.model_stage_attempts??0} / ${data.model_stage_budget}`));if(live){const stages=el('div',undefined,'stage-list');for(const stage of live.stages){const item=el('div',stage.name,'stage-item '+stage.status);item.append(el('small',statuses[stage.status]||stage.status));stages.append(item);}view.append(stages);if(live.error_detail||live.stop_reason)view.append(el('p',live.error_detail||live.stop_reason,data.status==='failed'?'blocker':''));}if(data.error&&!live?.error_detail&&data.error!==live?.stop_reason)view.append(el('p',data.error,'blocker'));const links=el('div',undefined,'result-links');if(live){const log=el('a','查看本轮日志 ↗');log.href='/logs?run='+encodeURIComponent(data.run_id);links.append(log);}if(data.status==='awaiting_human_review'){const review=el('a','进入本轮人工复核 →');review.href='/?run='+encodeURIComponent(data.run_id);links.append(review);}view.append(links);if(['queued','running'].includes(data.status))pollTimer=setTimeout(()=>chooseJob(id),2000);}catch(error){message(error.message);}}
$('samples').onchange=()=>{invalidate();refreshMetrics().catch(e=>message(e.message));const frame=$('metrics-frame');if(frame.contentWindow)frame.contentWindow.postMessage({type:'metrics-context',sample_id:$('samples').value},location.origin);};$('budget').onchange=invalidate;
$('register-form').onsubmit=async event=>{event.preventDefault();$('register').disabled=true;message('');try{const payload=Object.fromEntries(new FormData(event.currentTarget));if(!payload.sample_id)delete payload.sample_id;if(!payload.transcript)delete payload.transcript;const result=await api('/api/samples/register',payload);await loadSamples(result.sample_id);message(`已登记 ${result.sample_id}，尚未调用模型。`);}catch(error){message(error.message);}finally{$('register').disabled=false;}};
$('plan').onclick=async()=>{if(planning||launching)return;if($('metrics-record').value&&!$('metrics-match').checked){message('请先确认截图属于所选视频。');return;}planning=true;$('plan').disabled=true;message('');const version=++requestVersion;planned=null;$('start-actions').hidden=true;try{const rounds=Number($('budget').value);const data=await api('/api/jobs/plan',{sample_id:$('samples').value,max_model_calls:2+2*rounds,max_repair_rounds:rounds,metrics_record_id:$('metrics-record').value,metrics_match_confirmed:$('metrics-match').checked});if(version!==requestVersion)return;planned=data;showPlan(data);await refreshJobs(data.id);}catch(error){message(error.message);}finally{planning=false;$('plan').disabled=!samples.length;}};
$('start').onclick=async()=>{if(!planned||launching)return;launching=true;$('start').disabled=true;$('plan').disabled=true;message('');const job=planned;try{const data=await api('/api/jobs/start',{job_id:job.id});$('start-actions').hidden=true;planned=null;await refreshJobs(data.id);message('启动请求已处理。刷新或重复提交同一请求不会增加运行次数。');}catch(error){message(error.message+' 可以刷新记录检查状态；不会自动重试。');}finally{launching=false;$('plan').disabled=!samples.length;if(planned)$('start').disabled=!planned.ready;}};
$('jobs').onchange=()=>chooseJob($('jobs').value);
$('refresh').onclick=async()=>{try{await refreshJobs();}catch(error){message(error.message);}};
let metricRecords=[],metricRefresh=0;
async function refreshMetrics(preferred){const version=++metricRefresh;const sample=$('samples').value;const result=await api('/api/metrics');if(version!==metricRefresh||sample!==$('samples').value)return;metricRecords=result.records;const previous=preferred||$('metrics-record').value;$('metrics-record').replaceChildren(new Option('不使用截图数据（保留样本原有数据）',''));for(const r of metricRecords){const c=r.confirmation;if(r.status==='confirmed'&&c&&(!c.sample_id||c.sample_id===sample))$('metrics-record').add(new Option(`${c.title} · ${c.observed_at} · ${c.sample_id||'尚未关联视频'}`,r.id));}if(Array.from($('metrics-record').options).some(o=>o.value===previous))$('metrics-record').value=previous;metricsChanged();}
function metricsChanged(){invalidate();$('metrics-match').checked=false;const r=metricRecords.find(r=>r.id===$('metrics-record').value);if(!r){$('metrics-summary').textContent='未选择截图。可展开下方区域上传或核对已有记录。';return;}const c=r.confirmation;const labels={plays:'播放',likes:'点赞',comments:'评论',shares:'分享',favorites:'收藏',danmaku:'弹幕',completion_rate:'完播率',bounce_2s_rate:'2秒跳出率'};$('metrics-summary').textContent=Object.entries(c.normalized).filter(([,v])=>v!==null).map(([k,v])=>`${labels[k]} ${v}${k.endsWith('_rate')?'%':''}`).join(' · ')+`。统计范围：${{unknown:'尚未确认，只展示指标',cumulative:'截至截图累计',period:'指定时段'}[c.scope]}。`;
}
$('metrics-record').onchange=metricsChanged;$('metrics-match').onchange=invalidate;
$('refresh-metrics').onclick=()=>refreshMetrics().catch(e=>message(e.message));
$('metrics-editor').ontoggle=()=>{if($('metrics-editor').open&&!$('metrics-frame').getAttribute('src'))$('metrics-frame').src='/metrics?embed=1&sample='+encodeURIComponent($('samples').value);};
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.source!==$('metrics-frame').contentWindow)return;if(event.data?.type==='metrics-height'&&Number.isFinite(event.data.height))$('metrics-frame').style.height=Math.max(280,Math.min(5000,event.data.height))+'px';if(event.data?.type==='metrics-confirmed'){refreshMetrics(event.data.id).then(()=>message('截图已核对保存。请确认它属于所选视频，再预览计划。')).catch(e=>message(e.message));}});
async function init(){try{token=(await api('/api/session')).token;await loadSamples(new URLSearchParams(location.search).get('sample'));await refreshJobs(new URLSearchParams(location.search).get('job'));}catch(error){message(error.message);}}
init();
